B.a8A=s(["10. \u0627\u0644\u062a\u062d\u0643\u0645 \u0628\u0628\u064a\u0627\u0646\u0627\u062a\u0643","\u064a\u0645\u0643\u0646\u0643 \u062a\u0639\u062f\u064a\u0644 \u0645\u0644\u0641\u0643 \u0627\u0644\u0634\u062e\u0635\u064a\u060c \u0648\u062d\u0630\u0641 \u0645\u0646\u0634\u0648\u0631\u0627\u062a\u0643\u060c \u0648\u0636\u0628\u0637 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629 \u0648\u0627\u0644\u0625\u0634\u0639\u0627\u0631\u0627\u062a\u060c \u0648\u0625\u064a\u0642\u0627\u0641 \u062d\u0633\u0627\u0628\u0643 \u0645\u0624\u0642\u062a\u064b\u0627 \u0623\u0648 \u062d\u0630\u0641\u0647 \u0646\u0647\u0627\u0626\u064a\u064b\u0627 \u0645\u0646 \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a. \u0648\u0644\u0644\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0642\u0629 \u0628\u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u064a\u0645\u0643\u0646\u0643 \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0645\u0639\u0646\u0627 \u0639\u0644\u0649 \u0627\u0644\u0628\u0631\u064a\u062f \u0627\u0644\u0645\u0630\u0643\u0648\u0631 \u0623\u062f\u0646\u0627\u0647."],t.s)
B.ZV=s(["11. \u0645\u064a\u0632\u0629 Ghost \u0648\u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629","\u062a\u062a\u064a\u062d \u0645\u064a\u0632\u0629 Ghost \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0647\u0648\u064a\u0629 \u0645\u0633\u062a\u0639\u0627\u0631\u0629 \u0623\u0645\u0627\u0645 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u0644\u0622\u062e\u0631\u064a\u0646. \u0644\u0627 \u062a\u0639\u0646\u064a \u0623\u0646\u0646\u0627 \u0644\u0627 \u0646\u062c\u0645\u0639 \u0623\u064a \u0628\u064a\u0627\u0646\u0627\u062a \u0644\u0644\u062d\u0633\u0627\u0628\u060c \u0648\u0644\u0627 \u062a\u0636\u0645\u0646 \u0625\u062e\u0641\u0627\u0621 \u0627\u0644\u0647\u0648\u064a\u0629 \u0639\u0646 \u0627\u0644\u0628\u0646\u064a\u0629 \u0627\u0644\u062a\u0642\u0646\u064a\u0629 \u0644\u0644\u062a\u0637\u0628\u064a\u0642\u061b \u0641\u062a\u0638\u0644 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u064a \u064a\u062d\u062a\u0627\u062c\u0647\u0627 \u0627\u0644\u0646\u0638\u0627\u0645 \u0644\u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u062d\u0633\u0627\u0628 \u062e\u0627\u0636\u0639\u0629 \u0644\u0647\u0630\u0647 \u0627\u0644\u0633\u064a\u0627\u0633\u0629."],t.s)
B.ZS=s(["12. \u062e\u0635\u0648\u0635\u064a\u0629 \u0635\u063a\u0627\u0631 \u0627\u0644\u0633\u0646","\u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u063a\u064a\u0631 \u0645\u0648\u062c\u064e\u0651\u0647 \u0644\u0645\u0646 \u0647\u0645 \u062f\u0648\u0646 13 \u0639\u0627\u0645\u064b\u0627\u060c \u0648\u0644\u0627 \u0646\u0642\u0635\u062f \u062c\u0645\u0639 \u0628\u064a\u0627\u0646\u0627\u062a \u0645\u0646\u0647\u0645. \u0625\u0630\u0627 \u0639\u0644\u0645\u0646\u0627 \u0623\u0646 \u062d\u0633\u0627\u0628\u064b\u0627 \u064a\u0639\u0648\u062f \u0644\u0645\u0646 \u0647\u0648 \u062f\u0648\u0646 \u0627\u0644\u062d\u062f \u0627\u0644\u0639\u0645\u0631\u064a \u0627\u0644\u0645\u0637\u0628\u064e\u0651\u0642 \u0641\u0642\u062f \u0646\u063a\u0644\u0642\u0647 \u0648\u0646\u062d\u0630\u0641 \u0628\u064a\u0627\u0646\u0627\u062a\u0647."],t.s)
B.adt=s(["13. \u0627\u0644\u062a\u0639\u062f\u064a\u0644\u0627\u062a \u0639\u0644\u0649 \u0647\u0630\u0647 \u0627\u0644\u0633\u064a\u0627\u0633\u0629","\u0642\u062f \u0646\u062d\u062f\u0651\u062b \u0647\u0630\u0647 \u0627\u0644\u0633\u064a\u0627\u0633\u0629 \u0639\u0646\u062f \u062a\u063a\u064a\u064a\u0631 \u0648\u0638\u0627\u0626\u0641 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0623\u0648 \u0645\u0645\u0627\u0631\u0633\u0627\u062a \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0623\u0648 \u0627\u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629. \u0633\u0646\u0648\u0636\u062d \u062a\u0627\u0631\u064a\u062e \u0622\u062e\u0631 \u062a\u062d\u062f\u064a\u062b\u060c \u0648\u0633\u0646\u0628\u0644\u063a\u0643 \u0628\u0627\u0644\u062a\u063a\u064a\u064a\u0631\u0627\u062a \u0627\u0644\u062c\u0648\u0647\u0631\u064a\u0629 \u0628\u0637\u0631\u064a\u0642\u0629 \u0645\u0646\u0627\u0633\u0628\u0629 \u0645\u062a\u0649 \u0643\u0627\u0646 \u0630\u0644\u0643 \u0645\u0637\u0644\u0648\u0628\u064b\u0627."],t.s)
B.ZU=s(["14. \u0627\u0644\u062a\u0648\u0627\u0635\u0644 \u0628\u0634\u0623\u0646 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629","\u0644\u0644\u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a \u0623\u0648 \u0627\u0644\u0637\u0644\u0628\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0642\u0629 \u0628\u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u062a\u0648\u0627\u0635\u0644 \u0645\u0639\u0646\u0627 \u0639\u0628\u0631:\nlipogram.help@gmail.com\n\n\u064a\u064f\u0631\u062c\u0649 \u0639\u062f\u0645 \u0625\u0631\u0633\u0627\u0644 \u0643\u0644\u0645\u0627\u062a \u0627\u0644\u0645\u0631\u0648\u0631 \u0623\u0648 \u0623\u064a \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0633\u0631\u064a\u0629 \u0641\u064a \u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0627\u0633\u062a\u0641\u0633\u0627\u0631."],t.s)
