B.aeO=s(["1. \u0642\u0628\u0648\u0644 \u0627\u0644\u0634\u0631\u0648\u0637","\u0645\u0631\u062d\u0628\u064b\u0627 \u0628\u0643 \u0641\u064a Lipogram. \u062a\u0646\u0638\u0651\u0645 \u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0648\u0637 \u0648\u0627\u0644\u0623\u062d\u0643\u0627\u0645 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0643 \u0644\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u062e\u062f\u0645\u0627\u062a\u0647 \u0648\u0645\u064a\u0632\u0627\u062a\u0647. \u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0643 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0623\u0648 \u0625\u0646\u0634\u0627\u0626\u0643 \u062d\u0633\u0627\u0628\u064b\u0627 \u0641\u064a\u0647\u060c \u0641\u0625\u0646\u0643 \u062a\u0642\u0631\u0651 \u0628\u0623\u0646\u0643 \u0642\u0631\u0623\u062a\u0647\u0627 \u0648\u0641\u0647\u0645\u062a\u0647\u0627 \u0648\u0648\u0627\u0641\u0642\u062a \u0639\u0644\u0649 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0647\u0627. \u0625\u0646 \u0643\u0646\u062a \u0644\u0627 \u062a\u0648\u0627\u0641\u0642 \u0639\u0644\u0649 \u0623\u064a \u0645\u0646\u0647\u0627 \u0641\u064a\u064f\u0631\u062c\u0649 \u0639\u062f\u0645 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642."],t.s)
B.a_k=s(["2. \u0627\u0644\u0623\u0647\u0644\u064a\u0629 \u0627\u0644\u0639\u0645\u0631\u064a\u0629","\u064a\u064f\u0634\u062a\u0631\u0637 \u0623\u0644\u0627 \u064a\u0642\u0644 \u0639\u0645\u0631\u0643 \u0639\u0646 13 \u0639\u0627\u0645\u064b\u0627\u060c \u0645\u0639 \u0645\u0631\u0627\u0639\u0627\u0629 \u0623\u064a \u062d\u062f\u0651 \u0639\u0645\u0631\u064a \u0623\u0639\u0644\u0649 \u062a\u0641\u0631\u0636\u0647 \u0642\u0648\u0627\u0646\u064a\u0646 \u0628\u0644\u062f\u0643. \u0644\u0627 \u064a\u062c\u0648\u0632 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0644\u0645\u0646 \u0644\u0627 \u064a\u0633\u062a\u0648\u0641\u064a \u0627\u0644\u062d\u062f\u0651 \u0627\u0644\u0639\u0645\u0631\u064a \u0627\u0644\u0645\u0637\u0628\u064e\u0651\u0642 \u0639\u0644\u064a\u0647."],t.s)
B.a3R=s(["3. \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0645\u0633\u0624\u0648\u0644\u064a\u062a\u0643 \u0639\u0646\u0647","\u2022 \u0642\u062f\u0651\u0645 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0635\u062d\u064a\u062d\u0629 \u0639\u0646\u062f \u0625\u0646\u0634\u0627\u0621 \u062d\u0633\u0627\u0628\u0643\u060c \u0648\u062d\u062f\u0651\u062b\u0647\u0627 \u0639\u0646\u062f \u0627\u0644\u062d\u0627\u062c\u0629.\n\u2022 \u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0633\u0631\u064a\u0629 \u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062f\u062e\u0648\u0644 \u0648\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631\u060c \u0648\u0644\u0627 \u062a\u0634\u0627\u0631\u0643\u0647\u0627 \u0645\u0639 \u0623\u062d\u062f.\n\u2022 \u0644\u0627 \u064a\u062c\u0648\u0632 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u062d\u0633\u0627\u0628 \u0634\u062e\u0635 \u0622\u062e\u0631 \u062f\u0648\u0646 \u0625\u0630\u0646\u0647\u060c \u0648\u0644\u0627 \u0627\u0646\u062a\u062d\u0627\u0644 \u0647\u0648\u064a\u0629 \u0623\u064a \u0634\u062e\u0635 \u0623\u0648 \u062c\u0647\u0629.\n\u2022 \u0623\u0628\u0644\u063a\u0646\u0627 \u0641\u0648\u0631 \u0627\u0644\u0627\u0634\u062a\u0628\u0627\u0647 \u0641\u064a \u062f\u062e\u0648\u0644 \u063a\u064a\u0631 \u0645\u0635\u0631\u064e\u0651\u062d \u0628\u0647 \u0625\u0644\u0649 \u062d\u0633\u0627\u0628\u0643.\n\u2022 \u0623\u0646\u062a \u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0627\u0644\u0623\u0646\u0634\u0637\u0629 \u0627\u0644\u062a\u064a \u062a\u062a\u0645 \u0639\u0628\u0631 \u062d\u0633\u0627\u0628\u0643\u060c \u0628\u0627\u0644\u0642\u062f\u0631 \u0627\u0644\u0630\u064a \u064a\u0633\u0645\u062d \u0628\u0647 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u060c \u0648\u064a\u064f\u0633\u062a\u062b\u0646\u0649 \u0645\u0646 \u0630\u0644\u0643 \u0627\u0644\u0627\u062e\u062a\u0631\u0627\u0642 \u0623\u0648 \u0627\u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u063a\u064a\u0631 \u0627\u0644\u0645\u0635\u0631\u064e\u0651\u062d \u0628\u0647 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u0645\u0643\u0646 \u0646\u0633\u0628\u062a\u0647 \u0625\u0644\u064a\u0643."],t.s)
B.a07=s(["4. \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0648\u062d\u0642\u0648\u0642 \u0627\u0644\u0645\u0644\u0643\u064a\u0629","\u2022 \u062a\u062d\u062a\u0641\u0638 \u0628\u062d\u0642\u0648\u0642\u0643 \u0641\u064a \u0627\u0644\u0646\u0635\u0648\u0635 \u0648\u0627\u0644\u0623\u0639\u0645\u0627\u0644 \u0627\u0644\u0623\u0635\u0644\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0643\u062a\u0628\u0647\u0627 \u0648\u062a\u0646\u0634\u0631\u0647\u0627.\n\u2022 \u062a\u0645\u0646\u062d \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u062a\u0631\u062e\u064a\u0635\u064b\u0627 \u0645\u062d\u062f\u0648\u062f\u064b\u0627 \u0648\u063a\u064a\u0631 \u062d\u0635\u0631\u064a \u0644\u0627\u0633\u062a\u0636\u0627\u0641\u0629 \u0645\u062d\u062a\u0648\u0627\u0643 \u0648\u0639\u0631\u0636\u0647 \u0648\u0645\u0639\u0627\u0644\u062c\u062a\u0647 \u0628\u0627\u0644\u0642\u062f\u0631 \u0627\u0644\u0644\u0627\u0632\u0645 \u0644\u062a\u0634\u063a\u064a\u0644 \u0627\u0644\u062e\u062f\u0645\u0629\u060c \u0648\u0628\u062d\u0633\u0628 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u062e\u062a\u0627\u0631\u0647\u0627 \u0644\u0643\u0644 \u0645\u062d\u062a\u0648\u0649.\n\u2022 \u0644\u0627 \u064a\u0645\u0646\u062d \u0646\u0634\u0631\u064f\u0643 \u0645\u062d\u062a\u0648\u0627\u0643 \u0627\u0644\u062a\u0637\u0628\u064a\u0642\u064e \u062d\u0642\u064e\u0651 \u0627\u0645\u062a\u0644\u0627\u0643\u0647 \u0623\u0648 \u0628\u064a\u0639\u0647 \u0623\u0648 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647 \u0644\u0623\u063a\u0631\u0627\u0636 \u0645\u0633\u062a\u0642\u0644\u0629 \u0639\u0646 \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u062e\u062f\u0645\u0629\u060c \u0625\u0644\u0627 \u0628\u0645\u0648\u0627\u0641\u0642\u062a\u0643 \u0627\u0644\u0645\u0646\u0641\u0635\u0644\u0629 \u0623\u0648 \u0625\u0630\u0627 \u0623\u062c\u0627\u0632 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0630\u0644\u0643.\n\u2022 \u0623\u0646\u062a \u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0627\u0644\u062a\u0623\u0643\u062f \u0645\u0646 \u0623\u0646 \u0644\u062f\u064a\u0643 \u0627\u0644\u062d\u0642\u0648\u0642 \u0627\u0644\u0644\u0627\u0632\u0645\u0629 \u0644\u0646\u0634\u0631 \u0645\u0627 \u062a\u0631\u0641\u0639\u0647 \u0645\u0646 \u0646\u0635\u0648\u0635 \u0648\u0635\u0648\u0631 \u0648\u062a\u0633\u062c\u064a\u0644\u0627\u062a.\n\u2022 \u0639\u0646\u062f \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0645\u064a\u0632\u0629 \u0625\u0639\u0627\u062f\u0629 \u0627\u0644\u0645\u0632\u062c (Remix) \u064a\u062c\u0628 \u0627\u062d\u062a\u0631\u0627\u0645 \u062d\u0642\u0648\u0642 \u0635\u0627\u062d\u0628 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0623\u0635\u0644\u064a\u060c \u0648\u0630\u0643\u0631 \u0646\u0633\u0628\u062a\u0647 \u0625\u0644\u064a\u0647\u060c \u0648\u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0627\u0644\u0625\u0630\u0646 \u0627\u0644\u0630\u064a \u062d\u062f\u0651\u062f\u0647."],t.s)
B.a0H=s(["5. \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0648\u0627\u0644\u0633\u0644\u0648\u0643 \u0627\u0644\u0645\u062d\u0638\u0648\u0631","\u064a\u064f\u062d\u0638\u0631 \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0644\u0646\u0634\u0631 \u0623\u0648 \u0625\u0631\u0633\u0627\u0644 \u0623\u0648 \u0627\u0644\u062a\u0631\u0648\u064a\u062c \u0644\u0623\u064a \u0645\u0645\u0627 \u064a\u0623\u062a\u064a:\n\u2022 \u0627\u0644\u062a\u062d\u0631\u064a\u0636 \u0639\u0644\u0649 \u0627\u0644\u0643\u0631\u0627\u0647\u064a\u0629 \u0623\u0648 \u0627\u0644\u0639\u0646\u0641\u060c \u0623\u0648 \u0627\u0644\u062a\u0645\u064a\u064a\u0632 \u0636\u062f \u0627\u0644\u0623\u0634\u062e\u0627\u0635 \u0623\u0648 \u062a\u0647\u062f\u064a\u062f\u0647\u0645.\n\u2022 \u0627\u0644\u062a\u062d\u0631\u0634 \u0648\u0627\u0644\u062a\u0646\u0645\u0631 \u0648\u0627\u0644\u0645\u0636\u0627\u064a\u0642\u0629 \u0648\u0627\u0644\u062a\u0634\u0647\u064a\u0631 \u063a\u064a\u0631 \u0627\u0644\u0645\u0634\u0631\u0648\u0639.\n\u2022 \u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u062c\u0646\u0633\u064a \u0627\u0644\u0645\u062d\u0638\u0648\u0631\u060c \u0648\u0623\u064a \u0627\u0633\u062a\u063a\u0644\u0627\u0644 \u062c\u0646\u0633\u064a \u0644\u0644\u0642\u0627\u0635\u0631\u064a\u0646 \u0623\u0648 \u0645\u0648\u0627\u062f \u062a\u062a\u0639\u0644\u0642 \u0628\u0627\u0644\u0627\u0639\u062a\u062f\u0627\u0621 \u0639\u0644\u064a\u0647\u0645.\n\u2022 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u0644 \u0648\u0627\u0646\u062a\u062d\u0627\u0644 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0648\u0633\u0631\u0642\u0629 \u0627\u0644\u062d\u0633\u0627\u0628\u0627\u062a \u0648\u0646\u0634\u0631 \u0627\u0644\u0631\u0648\u0627\u0628\u0637 \u0627\u0644\u0636\u0627\u0631\u0629.\n\u2022 \u0627\u0644\u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0645\u0632\u0639\u062c\u0629 \u0648\u0627\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u063a\u064a\u0631 \u0627\u0644\u0645\u0635\u0631\u064e\u0651\u062d \u0628\u0647\u0627\u060c \u0648\u0643\u0644 \u0645\u0627 \u064a\u0639\u0637\u0651\u0644 \u062e\u062f\u0645\u0627\u062a \u0627\u0644\u062a\u0637\u0628\u064a\u0642.\n\u2022 \u0627\u0646\u062a\u0647\u0627\u0643 \u062d\u0642\u0648\u0642 \u0627\u0644\u0646\u0634\u0631 \u0623\u0648 \u0627\u0644\u0639\u0644\u0627\u0645\u0627\u062a \u0627\u0644\u062a\u062c\u0627\u0631\u064a\u0629 \u0623\u0648 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629 \u0623\u0648 \u0623\u064a \u062d\u0642\u0648\u0642 \u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0644\u0644\u0622\u062e\u0631\u064a\u0646.\n\u2022 \u0623\u064a \u0646\u0634\u0627\u0637 \u0622\u062e\u0631 \u064a\u062e\u0627\u0644\u0641 \u0627\u0644\u0642\u0648\u0627\u0646\u064a\u0646 \u0627\u0644\u0645\u0639\u0645\u0648\u0644 \u0628\u0647\u0627 \u0623\u0648 \u064a\u0647\u062f\u062f \u0633\u0644\u0627\u0645\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646."],t.s)
B.a_B=s(["6. \u062d\u0633\u0627\u0628 Ghost","\u064a\u062a\u064a\u062d \u0644\u0643 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u062d\u0633\u0627\u0628 Ghost \u0644\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0633\u0645 \u0645\u0633\u062a\u0639\u0627\u0631 \u0648\u0625\u062e\u0641\u0627\u0621 \u0647\u0648\u064a\u062a\u0643 \u0627\u0644\u062d\u0642\u064a\u0642\u064a\u0629 \u0639\u0646 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0627\u0644\u0622\u062e\u0631\u064a\u0646\u060c \u0648\u0641\u0642 \u0627\u0644\u062e\u0635\u0627\u0626\u0635 \u0648\u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0645\u062a\u0627\u062d\u0629. \u0644\u0627 \u062a\u0639\u0646\u064a \u0647\u0630\u0647 \u0627\u0644\u0645\u064a\u0632\u0629 \u0636\u0645\u0627\u0646 \u0625\u062e\u0641\u0627\u0621 \u0627\u0644\u0647\u0648\u064a\u0629 \u0639\u0646 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0623\u0648 \u0639\u0646 \u0627\u0644\u062c\u0647\u0627\u062a \u0627\u0644\u062a\u0642\u0646\u064a\u0629 \u0627\u0644\u062a\u064a \u064a\u0639\u062a\u0645\u062f \u0639\u0644\u064a\u0647\u0627\u060c \u0648\u0644\u0627 \u062a\u0639\u0641\u064a \u0635\u0627\u062d\u0628\u0647\u0627 \u0645\u0646 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0628\u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0648\u0637. \u0648\u064a\u062c\u0648\u0632 \u0627\u062a\u062e\u0627\u0630 \u0627\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a \u0627\u0644\u0645\u0646\u0627\u0633\u0628\u0629 \u0628\u062d\u0642 \u0623\u064a \u062d\u0633\u0627\u0628 Ghost \u062a\u062b\u0628\u062a \u0625\u0633\u0627\u0621\u0629 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0647."],t.s)
B.a9k=s(["7. \u0627\u0644\u0642\u0635\u0635 \u0648\u0627\u0644\u0645\u0633\u0627\u0628\u0642\u0627\u062a","\u0627\u0644\u0642\u0635\u0635 \u0645\u062d\u062a\u0648\u0649 \u0645\u0624\u0642\u062a \u064a\u064f\u062d\u0630\u0641 \u062a\u0644\u0642\u0627\u0626\u064a\u064b\u0627 \u0628\u0639\u062f \u0627\u0646\u062a\u0647\u0627\u0621 \u0627\u0644\u0645\u062f\u0629 \u0627\u0644\u062a\u064a \u0627\u062e\u062a\u0627\u0631\u0647\u0627 \u0635\u0627\u062d\u0628\u0647\u0627. \u0648\u0627\u0644\u0645\u0633\u0627\u0628\u0642\u0627\u062a \u062a\u062e\u0636\u0639 \u0644\u0634\u0631\u0648\u0637\u0647\u0627 \u0627\u0644\u0645\u0639\u0644\u0646\u0629 \u0639\u0646\u062f \u0625\u0646\u0634\u0627\u0626\u0647\u0627\u060c \u0648\u062a\u064f\u062d\u0630\u0641 \u0628\u0637\u0627\u0642\u0629 \u0627\u0644\u0645\u0633\u0627\u0628\u0642\u0629 \u0628\u0627\u0646\u062a\u0647\u0627\u0621 \u0648\u0642\u062a\u0647\u0627\u060c \u0648\u062a\u0628\u0642\u0649 \u0642\u0646\u0627\u062a\u0647\u0627 \u0648\u0645\u062d\u062a\u0648\u064a\u0627\u062a\u0647\u0627 \u0648\u0641\u0642 \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a. \u0648\u064a\u0644\u062a\u0632\u0645 \u0627\u0644\u0645\u0634\u0627\u0631\u0643\u0648\u0646 \u0641\u064a\u0647\u0627 \u0628\u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0648\u0637 \u0648\u0628\u0642\u0648\u0627\u0639\u062f \u0643\u0644 \u0645\u0633\u0627\u0628\u0642\u0629."],t.s)
B.a53=s(["8. \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0648\u0627\u0644\u0645\u0631\u0627\u062c\u0639\u0629 \u0648\u0627\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a","\u064a\u0645\u0643\u0646 \u0644\u0623\u064a \u0645\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u0625\u0628\u0644\u0627\u063a \u0639\u0646 \u062d\u0633\u0627\u0628 \u0623\u0648 \u0645\u0646\u0634\u0648\u0631 \u0623\u0648 \u062a\u0639\u0644\u064a\u0642 \u0623\u0648 \u0631\u0633\u0627\u0644\u0629 \u064a\u0631\u0649 \u0623\u0646\u0647\u0627 \u062a\u062e\u0627\u0644\u0641 \u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0648\u0637. \u0642\u062f \u064a\u0633\u062a\u062e\u062f\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0623\u062f\u0648\u0627\u062a \u0622\u0644\u064a\u0629\u060c \u0643\u0645\u0631\u0634\u0651\u062d\u0627\u062a \u0627\u0644\u0643\u0644\u0645\u0627\u062a\u060c \u0644\u0645\u0633\u0627\u0639\u062f\u062a\u0647 \u0641\u064a \u0627\u0644\u0643\u0634\u0641 \u0639\u0646 \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u0627\u062a\u060c \u0648\u064a\u0631\u0627\u062c\u0639 \u0627\u0644\u0645\u0634\u0631\u0641\u0648\u0646 \u0627\u0644\u0628\u0644\u0627\u063a\u0627\u062a.\n\n\u0628\u062d\u0633\u0628 \u0637\u0628\u064a\u0639\u0629 \u0627\u0644\u0645\u062e\u0627\u0644\u0641\u0629 \u0648\u062e\u0637\u0648\u0631\u062a\u0647\u0627\u060c \u0642\u062f \u0646\u062a\u062e\u0630 \u0625\u062c\u0631\u0627\u0621\u064b \u0645\u0646\u0627\u0633\u0628\u064b\u0627\u060c \u0648\u0645\u0646\u0647: \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0645\u062d\u062a\u0648\u0649\u060c \u0623\u0648 \u062a\u0642\u064a\u064a\u062f \u0628\u0639\u0636 \u0627\u0644\u0645\u064a\u0632\u0627\u062a\u060c \u0623\u0648 \u0627\u0644\u0625\u064a\u0642\u0627\u0641 \u0627\u0644\u0645\u0624\u0642\u062a \u0644\u0644\u062d\u0633\u0627\u0628\u060c \u0623\u0648 \u0625\u0646\u0647\u0627\u0624\u0647. \u0648\u062a\u064f\u0631\u0627\u0639\u0649 \u0627\u0644\u0642\u0648\u0627\u0646\u064a\u0646 \u0627\u0644\u0645\u0639\u0645\u0648\u0644 \u0628\u0647\u0627 \u0648\u062d\u0642\u0648\u0642 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646 \u0639\u0646\u062f \u0627\u062a\u062e\u0627\u0630 \u0647\u0630\u0647 \u0627\u0644\u0625\u062c\u0631\u0627\u0621\u0627\u062a."],t.s)
B.a16=s(["9. \u0625\u064a\u0642\u0627\u0641 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u062d\u0630\u0641\u0647","\u064a\u0645\u0643\u0646\u0643 \u0645\u0646 \u0627\u0644\u0625\u0639\u062f\u0627\u062f\u0627\u062a \u2190 Account \u0625\u064a\u0642\u0627\u0641 \u062d\u0633\u0627\u0628\u0643 \u0645\u0624\u0642\u062a\u064b\u0627 \u0623\u0648 \u062d\u0630\u0641\u0647 \u0646\u0647\u0627\u0626\u064a\u064b\u0627. \u0639\u0646\u062f \u0637\u0644\u0628 \u0627\u0644\u062d\u0630\u0641 \u064a\u064f\u063a\u0644\u0642 \u0627\u0644\u062d\u0633\u0627\u0628 \u0641\u0648\u0631\u064b\u0627 \u0648\u064a\u062e\u062a\u0641\u064a \u0639\u0646 \u0627\u0644\u0622\u062e\u0631\u064a\u0646\u060c \u062b\u0645 \u064a\u064f\u062d\u0630\u0641 \u0646\u0647\u0627\u0626\u064a\u064b\u0627 \u0628\u0639\u062f 14 \u064a\u0648\u0645\u064b\u0627\u060c \u0648\u064a\u064f\u0644\u063a\u0649 \u0627\u0644\u062d\u0630\u0641 \u0625\u0646 \u0633\u062c\u0651\u0644\u062a \u0627\u0644\u062f\u062e\u0648\u0644 \u062e\u0644\u0627\u0644 \u0647\u0630\u0647 \u0627\u0644\u0645\u062f\u0629. \u0627\u0644\u062d\u0630\u0641 \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0644\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062a\u0631\u0627\u062c\u0639 \u0639\u0646\u0647\u060c \u0648\u0642\u062f \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u0641\u0642\u062f\u0627\u0646 \u0627\u0644\u062d\u0633\u0627\u0628 \u0648\u0645\u062d\u062a\u0648\u0627\u0647 \u0648\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0645\u0631\u062a\u0628\u0637\u0629 \u0628\u0647. \u0648\u062a\u062e\u0636\u0639 \u0645\u0639\u0627\u0644\u062c\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0644\u0633\u064a\u0627\u0633\u0629 \u0627\u0644\u062e\u0635\u0648\u0635\u064a\u0629 \u0648\u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645\u0627\u062a \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a\u0629 \u0630\u0627\u062a \u0627\u0644\u0635\u0644\u0629."],t.s)
B.a_N=s(["10. \u062a\u0648\u0641\u0651\u0631 \u0627\u0644\u062e\u062f\u0645\u0629 \u0648\u0625\u062e\u0644\u0627\u0621 \u0627\u0644\u0645\u0633\u0624\u0648\u0644\u064a\u0629","\u064a\u064f\u0642\u062f\u064e\u0651\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0628\u062d\u0633\u0628 \u0625\u0645\u0643\u0627\u0646\u0627\u062a\u0647 \u0627\u0644\u062a\u0642\u0646\u064a\u0629 \u0627\u0644\u062d\u0627\u0644\u064a\u0629. \u0646\u0628\u0630\u0644 \u062c\u0647\u062f\u064b\u0627 \u0645\u0639\u0642\u0648\u0644\u064b\u0627 \u0644\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0631\u0627\u0631\u0647 \u0648\u0623\u0645\u0627\u0646\u0647\u060c \u062f\u0648\u0646 \u0636\u0645\u0627\u0646 \u062e\u0644\u0648\u0651\u0647 \u0645\u0646 \u0627\u0644\u0623\u062e\u0637\u0627\u0621 \u0623\u0648 \u062a\u0648\u0641\u0631\u0647 \u062f\u0648\u0646 \u0627\u0646\u0642\u0637\u0627\u0639. \u0648\u0644\u0627 \u064a\u062d\u062f\u0651 \u0647\u0630\u0627 \u0627\u0644\u0628\u0646\u062f \u0645\u0646 \u0623\u064a \u062d\u0642\u0648\u0642 \u0623\u0648 \u0636\u0645\u0627\u0646\u0627\u062a \u0644\u0627 \u064a\u062c\u0648\u0632 \u0627\u0633\u062a\u0628\u0639\u0627\u062f\u0647\u0627 \u0628\u0645\u0648\u062c\u0628 \u0627\u0644\u0642\u0627\u0646\u0648\u0646 \u0627\u0644\u0645\u0639\u0645\u0648\u0644 \u0628\u0647."],t.s)
B.a2p=s(["11. \u062a\u0639\u062f\u064a\u0644 \u0627\u0644\u0634\u0631\u0648\u0637","\u0642\u062f \u0646\u062d\u062f\u0651\u062b \u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0648\u0637 \u0639\u0646\u062f \u062a\u0637\u0648\u064a\u0631 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0623\u0648 \u062a\u063a\u064a\u064a\u0631 \u062e\u062f\u0645\u0627\u062a\u0647 \u0623\u0648 \u0639\u0646\u062f \u0627\u0644\u062d\u0627\u062c\u0629 \u0625\u0644\u0649 \u0627\u0644\u0627\u0645\u062a\u062b\u0627\u0644 \u0644\u0645\u062a\u0637\u0644\u0628\u0627\u062a \u0642\u0627\u0646\u0648\u0646\u064a\u0629. \u0648\u0633\u0646\u062e\u0637\u0631\u0643 \u0628\u0627\u0644\u062a\u063a\u064a\u064a\u0631\u0627\u062a \u0627\u0644\u062c\u0648\u0647\u0631\u064a\u0629 \u0628\u0637\u0631\u064a\u0642\u0629 \u0645\u0646\u0627\u0633\u0628\u0629 \u0642\u0628\u0644 \u0633\u0631\u064a\u0627\u0646\u0647\u0627 \u0645\u062a\u0649 \u0643\u0627\u0646 \u0630\u0644\u0643 \u0645\u0637\u0644\u0648\u0628\u064b\u0627\u060c \u0648\u064a\u0639\u0646\u064a \u0627\u0633\u062a\u0645\u0631\u0627\u0631\u0643 \u0641\u064a \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0628\u0639\u062f \u0627\u0644\u062a\u062d\u062f\u064a\u062b \u0642\u0628\u0648\u0644\u0643 \u0644\u0644\u0634\u0631\u0648\u0637 \u0627\u0644\u0645\u062d\u062f\u064e\u0651\u062b\u0629."],t.s)
B.a0Q=s(["12. \u0623\u062d\u0643\u0627\u0645 \u0639\u0627\u0645\u0629","\u062a\u064f\u0641\u0633\u064e\u0651\u0631 \u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0648\u0637 \u0648\u062a\u064f\u0637\u0628\u064e\u0651\u0642 \u0648\u0641\u0642 \u0627\u0644\u0642\u0648\u0627\u0646\u064a\u0646 \u0627\u0644\u0645\u0639\u0645\u0648\u0644 \u0628\u0647\u0627 \u0648\u0627\u0644\u062d\u0642\u0648\u0642 \u0627\u0644\u0625\u0644\u0632\u0627\u0645\u064a\u0629 \u0627\u0644\u0645\u0642\u0631\u064e\u0651\u0631\u0629 \u0644\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u064a\u0646. \u0648\u0625\u0630\u0627 \u062a\u0628\u064a\u0651\u0646 \u0623\u0646 \u062d\u0643\u0645\u064b\u0627 \u0645\u0646\u0647\u0627 \u063a\u064a\u0631 \u0642\u0627\u0628\u0644 \u0644\u0644\u062a\u0646\u0641\u064a\u0630 \u0641\u0644\u0627 \u064a\u0624\u062b\u0631 \u0630\u0644\u0643 \u0641\u064a \u0628\u0642\u064a\u0629 \u0627\u0644\u0623\u062d\u0643\u0627\u0645 \u0628\u0627\u0644\u0642\u062f\u0631 \u0627\u0644\u0630\u064a \u064a\u0633\u0645\u062d \u0628\u0647 \u0627\u0644\u0642\u0627\u0646\u0648\u0646."],t.s)
B.a1_=s(["13. \u0627\u0644\u062a\u0648\u0627\u0635\u0644","\u0644\u0644\u0627\u0633\u062a\u0641\u0633\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u062a\u0639\u0644\u0642\u0629 \u0628\u0647\u0630\u0647 \u0627\u0644\u0634\u0631\u0648\u0637 \u062a\u0648\u0627\u0635\u0644 \u0645\u0639\u0646\u0627 \u0639\u0628\u0631 \u0627\u0644\u0628\u0631\u064a\u062f \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a:\nlipogram.help@gmail.com"],t.s)
